package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.relationship.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class Phase4BehaviorGameTest {
 @GameTest public void sleepingStateIsPersisted(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);c.setNight();c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var s=NpcActivityManager.get(c.getLevel().getServer()).get(v.getUUID());if(s==null||s.activity()!=NpcActivity.SLEEPING){c.fail("Villager did not enter persistent sleeping state");return;}c.succeed();});}
 @GameTest public void trustedVillagerFollowsPlayer(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);var p=c.makeMockServerPlayerInLevel();p.setPos(5,1,2);var rm=RelationshipManager.get(c.getLevel().getServer());for(int i=0;i<8;i++)rm.apply(new MemoryEvent(v.getUUID(),p.getUUID(),com.wizzadrds.theworldremembers.memory.MemoryEventType.PLAYER_SAVED_NPC,c.getLevel().getGameTime(),com.wizzadrds.theworldremembers.memory.MemoryImportance.IMPORTANT));c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var s=NpcActivityManager.get(c.getLevel().getServer()).get(v.getUUID());if(s==null||s.activity()!=NpcActivity.FOLLOWING_PLAYER||!p.getUUID().equals(s.target())){c.fail("Trusted villager did not enter follow state");return;}c.succeed();});}
}
